import MetricCard from "@/components/MetricCard";

export default function Home() {
  return (
    <main className="flex min-h-screen flex-col items-center p-8 gap-8">
      <div className="text-center">
        <h1 className="text-4xl font-bold text-amdred">Edge-Pali</h1>
        <p className="text-gray-400 mt-2 font-mono">Dynamic VRAM Optimizer</p>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 w-full max-w-4xl">
        <MetricCard label="Latency" value="56.5" unit="ms" accent="red" />
        <MetricCard label="Footprint Reduction" value="12.4" unit="%" accent="orange" />
        <MetricCard label="Original Patches" value="1024" accent="red" />
        <MetricCard label="Pruned Patches" value="897" accent="orange" />
      </div>
    </main>
  );
}